class Solution {
    fun getSubarrayBeauty(nums:IntArray,k:Int,x:Int):IntArray{
        val frequency=IntArray(101);
        val answer=IntArray(nums.size-k+1);
        for(i in 0 until k)frequency[nums[i]+50]++;
        for(start in answer.indices){
            var count=0;
            for(index in 0 until 50){
                count+=frequency[index];
                if(count>=x){
                    answer[start]=index-50;
                    break
                }
            };
            frequency[nums[start]+50]--;
            if(start+k<nums.size)frequency[nums[start+k]+50]++
        };
        return answer
    }
}

